css:
:root {
  --primary: #ff8b3d;
  --primary-hover: #ff6b1d;
  --bg: #0d0b0c;
  --bg-alt: #181213;
  --card-bg: rgba(28, 19, 18, 0.94);
  --text: #f9eee6;
  --text-secondary: #f5cbb5;
  --border: #3a2a27;
  --ember: #ffae3d;
  --slag: #332322;
  --shadow-forge: 0 16px 36px rgba(0,0,0,0.55);
}

body {
  background: radial-gradient(circle at 20% 10%, rgba(255, 139, 61, 0.12), transparent 35%),
              radial-gradient(circle at 80% 0%, rgba(255, 110, 48, 0.1), transparent 30%),
              linear-gradient(180deg, #0b090a 0%, #120c0c 40%, #1a1212 100%);
  color: var(--text);
}

.header {
  background: linear-gradient(110deg, rgba(255, 139, 61, 0.35) 0%, rgba(255, 90, 31, 0.4) 40%, rgba(149, 64, 43, 0.45) 100%);
  border-bottom: 3px solid var(--primary);
  box-shadow: 0 14px 32px rgba(0,0,0,0.55), inset 0 -2px 0 rgba(255,255,255,0.08);
}

.brand {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: #fff6ed;
  text-shadow: 0 0 12px rgba(255,139,61,0.8), 0 0 28px rgba(255,107,29,0.6);
}

.card {
  background: linear-gradient(160deg, rgba(28, 19, 18, 0.98) 0%, rgba(18, 12, 11, 0.95) 100%);
  border: 1px solid rgba(255,139,61,0.25);
  border-radius: 14px;
  box-shadow: var(--shadow-forge);
  position: relative;
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.18s ease;
}

.card::before {
  content: "";
  position: absolute;
  inset: -30% -10% 45% -10%;
  background: radial-gradient(ellipse at 45% 35%, rgba(255,139,61,0.28) 0%, transparent 60%),
              radial-gradient(ellipse at 65% 25%, rgba(255,174,61,0.22) 0%, transparent 55%);
  filter: blur(10px);
}

.card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,139,61,0.12), rgba(149,64,43,0.08));
  mix-blend-mode: screen;
}

.card:hover {
  transform: translateY(-6px);
  border-color: rgba(255,139,61,0.55);
  box-shadow: 0 24px 50px rgba(0,0,0,0.65), 0 0 0 2px rgba(255,139,61,0.25);
}

.card .card-title {
  color: #fff7ef;
  letter-spacing: 0.02em;
  font-weight: 800;
}

.card .card-body {
  color: var(--text-secondary);
  line-height: 1.7;
}

.card .tag,
.card .label {
  background: linear-gradient(120deg, rgba(255,139,61,0.9) 0%, rgba(255,174,61,0.9) 100%);
  color: #31190f;
  border: 1px solid rgba(255,139,61,0.65);
  border-radius: 999px;
  box-shadow: 0 0 16px rgba(255,139,61,0.35);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sidebar,
.panel,
.modal,
.popover {
  background: rgba(18, 12, 11, 0.92);
  border: 1px solid rgba(255,139,61,0.2);
  box-shadow: 0 18px 38px rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
}

.list-item,
.menu-item,
.dropdown-item {
  background: rgba(27, 18, 16, 0.88);
  border-radius: 12px;
  border: 1px solid rgba(255,139,61,0.18);
  transition: background 0.16s ease, transform 0.16s ease;
}

.list-item:hover,
.menu-item:hover,
.dropdown-item:hover {
  background: rgba(36, 24, 21, 0.92);
  transform: translateX(5px);
  box-shadow: 0 12px 28px rgba(0,0,0,0.45);
}

.progress,
.timeline::before,
.board::before {
  background: linear-gradient(90deg, rgba(255,139,61,0.35), rgba(255,174,61,0.25), rgba(255,139,61,0.35));
}

.floating-ribbon {
  background: linear-gradient(100deg, #ffae3d 0%, #ff8b3d 60%, #ff6b1d 100%);
  color: #2a140c;
  box-shadow: 0 16px 34px rgba(0,0,0,0.55);
}
